package com.tripnest.controller;
import com.tripnest.dto.ApiDtos.*; import com.tripnest.service.BookingService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/bookings") public class BookingController { private final BookingService service; public BookingController(BookingService s){service=s;} @GetMapping public List<BookingView> mine(@RequestParam(required=false) String email,Authentication authentication){if(email!=null&&!email.equalsIgnoreCase(authentication.getName()))throw new com.tripnest.exception.ApiException(HttpStatus.FORBIDDEN,"You can only view your own bookings.");return service.mine(authentication.getName());} @PostMapping("/accommodations/{id}") public BookingView create(@PathVariable Long id,@Valid @RequestBody BookingRequest request,Authentication authentication){return service.create(authentication.getName(),id,request);} @PostMapping("/{reference}/cancel") public Map<String,String> cancel(@PathVariable String reference,Authentication authentication){service.cancel(authentication.getName(),reference);return Map.of("message","Booking cancelled.");} @DeleteMapping("/{reference}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String reference,Authentication authentication){service.cancel(authentication.getName(),reference);} }
